<script setup lang="ts">
import { chartColors } from '../theme'
import { computed,ref,watch,onBeforeUnmount } from 'vue'
import { get } from '../api'
import type { Timeline,EventRow,Params } from '../api'
import { filters,exportJson,useViewReadiness,selection } from '../store'
const props=defineProps<{revision:number;resetKey:number}>()
const emit=defineEmits<{evidence:[id:string];entity:[id:string]}>()
const data=ref<Timeline>(),type=ref(''),outliers=ref(false),missing=ref(false),page=ref(1),error=ref(''),busy=ref(false)
const eventFilters=computed(()=>({...filters.value,event_type:type.value,include_outliers:outliers.value,missing_only:missing.value}))
const loadedFilters=ref<Params>()
const exportReady=computed(()=>!!data.value&&!busy.value&&!error.value&&JSON.stringify(loadedFilters.value)===JSON.stringify(eventFilters.value))
useViewReadiness('events',()=>exportReady.value)
function exportScope(){if(exportReady.value)exportJson('mc3-event-scope.json',{filters:loadedFilters.value,...data.value})}
let request=0
const host=ref<HTMLElement>(),chartWidth=ref(708)
let observer:ResizeObserver|undefined
watch(host,node=>{observer?.disconnect();if(node){observer=new ResizeObserver(()=>chartWidth.value=Math.max(320,node.clientWidth-28));observer.observe(node)}},{flush:'post'})
onBeforeUnmount(()=>observer?.disconnect())
async function load(){const current=++request;busy.value=true;error.value='';try{const snapshot={...eventFilters.value};const params={...snapshot,page_size:100};const first=await get<Timeline>('events/timeline',{...params,page:1});const items=[...first.items];for(let n=2;n<=Math.ceil(first.total/100);n++){if(current!==request)return;items.push(...(await get<Timeline>('events/timeline',{...params,page:n})).items)}if(current===request){data.value={...first,items};loadedFilters.value=snapshot}}catch(e){if(current===request)error.value=(e as Error).message}finally{if(current===request)busy.value=false}}
watch([filters,type,outliers,missing],()=>{page.value=1;load()},{immediate:true})
watch(()=>props.resetKey,()=>{type.value='';outliers.value=false;missing.value=false;page.value=1})
function describe(row:EventRow){for(const field of ['findings','results','outcome','destination','monitoring_type','movement_type','reference'])if(row.node[field])return String(row.node[field]);return '选择事件检查参与主体、原始字段和支撑通信。'}
const dated=computed(()=>data.value?.items.filter(row=>row.timestamp)||[])
const pageItems=computed(()=>data.value?.items.slice((page.value-1)*15,page.value*15)||[])
const dayCounts=computed(()=>[...new Set(dated.value.map(row=>row.timestamp!.slice(0,10)))].sort().map(day=>({day,count:dated.value.filter(row=>row.timestamp!.startsWith(day)).length})))
const maxDay=computed(()=>Math.max(1,...dayCounts.value.map(row=>row.count)))
const lanes=computed(()=>[...new Set(dated.value.flatMap(row=>row.participants))].sort((a,b)=>Number(b===selection.entity)-Number(a===selection.entity)||a.localeCompare(b)))
const timeExtent=computed(()=>{const times=dated.value.map(row=>new Date(row.timestamp!.replace(' ','T')).getTime());return times.length?[Math.min(...times),Math.max(...times)]:[0,1]})
function eventX(row:EventRow){const time=new Date(row.timestamp!.replace(' ','T')).getTime();return 158+(time-timeExtent.value[0]!)/Math.max(1,timeExtent.value[1]!-timeExtent.value[0]!)*(chartWidth.value-188)}
function laneY(id:string){return 42+lanes.value.indexOf(id)*26}
function inspect(row:EventRow){emit('evidence',row.id)}
</script>
<template><div ref="host" class="event-controls"><select v-model="type" aria-label="事件类型"><option value="">全部事件类型</option><option v-for="t in data?.types" :key="t">{{t}}</option></select><label><input type="checkbox" v-model="missing" data-testid="missing-events">缺失 timestamp</label><label><input type="checkbox" v-model="outliers" data-testid="include-outliers">含观察期外</label><button class="chip" :disabled="!exportReady" @click="exportScope">↓ 导出</button></div><div v-if="error" class="error">{{error}}</div><div v-if="busy&&!data" class="empty">正在查询事件…</div><div v-if="dayCounts.length" class="event-day-chart"><h3>全期事件分布</h3><svg data-testid="event-day-overview" :viewBox="`0 0 ${chartWidth} 92`" aria-label="全范围事件每日计数"><g v-for="(day,i) in dayCounts" :key="day.day"><rect :x="i*(chartWidth-8)/dayCounts.length+4" :y="65-day.count/maxDay*48" :width="Math.max(2,(chartWidth-8)/dayCounts.length-8)" :height="day.count/maxDay*48" :fill="chartColors.blue"/><text :x="(i+.5)*(chartWidth-8)/dayCounts.length" y="83" text-anchor="middle" font-size="10" :fill="chartColors.muted">{{day.day.slice(5)}}</text><text :x="(i+.5)*(chartWidth-8)/dayCounts.length" :y="61-day.count/maxDay*48" text-anchor="middle" font-size="10" :fill="chartColors.muted">{{day.count}}</text><title>{{day.day}} · {{day.count}} 个事件</title></g></svg></div><div class="event-map scroll" v-if="dated.length&&lanes.length"><h3>主体事件分布</h3><svg data-testid="event-swimlane" :viewBox="`0 0 ${chartWidth} ${Math.max(120,lanes.length*26+65)}`" aria-label="主体事件泳道"><text x="158" y="17" font-size="11" :fill="chartColors.muted">{{dated[0]?.timestamp?.slice(5,16)}}</text><text :x="chartWidth-30" y="17" font-size="11" :fill="chartColors.muted" text-anchor="end">{{dated[dated.length-1]?.timestamp?.slice(5,16)}}</text><g v-for="lane in lanes" :key="lane"><line x1="153" :x2="chartWidth-20" :y1="laneY(lane)" :y2="laneY(lane)" :stroke="chartColors.line"/><text x="144" :y="laneY(lane)+4" text-anchor="end" font-size="12" :fill="chartColors.ink">{{lane}}</text></g><g v-for="row in dated" :key="row.id" class="swimlane-event" role="button" tabindex="0" :aria-label="row.id" @click="inspect(row)" @keydown.enter.prevent="inspect(row)"><line v-if="row.participants.length" :x1="eventX(row)" :x2="eventX(row)" :y1="Math.min(...row.participants.map(laneY))" :y2="Math.max(...row.participants.map(laneY))" :stroke="chartColors.edge" stroke-dasharray="3 3"/><circle v-for="actor in row.participants" :key="actor" :cx="eventX(row)" :cy="laneY(actor)" r="4" :fill="chartColors.blue" :stroke="chartColors.panel"/><title>{{row.id}} · {{row.timestamp}}&#10;{{row.participants.join('、')}}&#10;{{row.evidence_ids.length}} 条支撑通信</title></g></svg></div><details class="event-reading"><summary>事件范围与图例</summary><p class="panel-note">{{data?.total||0}} 个事件 · {{data?.undated||0}} 个未定时 · 默认排除 {{data?.excluded_outliers||0}} 个观察期外事件 · 文本推断事件</p><p>日期图统计全期有日期事件，未定时记录列在下方。主体图展示当前范围的全部事件，连线连接同一事件的参与者。</p></details><div class="event-scroll scroll"><div class="event-chain" v-if="data?.items.length"><article v-for="row in pageItems" :key="row.id" data-testid="timeline-event"><div class="event-dot" :class="row.time_status"></div><div class="event-time">{{row.timestamp||'时间未指定'}} <span>{{row.time_source}}</span><span class="badge warning" v-if="row.time_status==='out_of_window'">观察期外 · 保留原值</span></div><div class="event-title"><span class="badge inferred">{{row.sub_type}}</span><button class="link mono" @click="emit('evidence',row.id)">{{row.id}}</button></div><p>{{describe(row)}}</p><div class="event-actors"><button v-for="id in row.participants" :key="id" class="chip" @click="emit('entity',id)">{{id}}</button></div><div class="event-support"><span>由 {{row.evidence_ids.length}} 条原始通信支撑：</span><button v-for="id in row.evidence_ids.slice(0,3)" :key="id" class="link mono" @click="emit('evidence',id)">{{id}}</button><button v-if="row.evidence_ids.length>3" class="link" @click="emit('evidence',row.id)">全部 →</button></div></article></div><div v-else class="empty">当前范围没有关联事件。<br>可以选择其他主体，或检查缺失时间及观察期外记录。</div></div><div class="event-pagination"><button :disabled="page===1" @click="page--">←</button><span>{{page}} / {{Math.max(1,Math.ceil((data?.total||0)/15))}}</span><button :disabled="page*15>=(data?.total||0)" @click="page++">→</button></div></template>
<style scoped>
.event-day-chart h3,.event-map h3{font-size:13px;font-weight:600;color:var(--ink);margin:6px 0 12px}.event-reading{margin:12px 14px;font-size:13px;color:var(--ink);line-height:1.8}.event-reading summary{cursor:pointer}.event-reading .panel-note{padding:8px 0}

.event-controls{display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 14px 0}.event-controls select{font-size:12px;padding:5px;max-width:175px}.event-controls label{font-size:12px;color:var(--muted);display:flex;gap:4px;align-items:center}.event-controls input{margin:0}.event-controls>.chip{margin-left:auto}.event-map{max-height:255px;border-top:1px solid var(--selected);border-bottom:1px solid var(--selected);padding:10px}.event-map svg{width:100%;min-width:0;display:block}.swimlane-event{cursor:pointer}.swimlane-event:hover circle,.swimlane-event:focus circle{fill:#bc862d;r:6}.event-scroll{max-height:480px;min-height:180px}.event-chain{padding:16px 14px 5px 25px}.event-chain article{position:relative;border-left:1px solid var(--border);padding:0 0 23px 18px}.event-dot{position:absolute;left:-4px;top:5px;width:7px;height:7px;border-radius:50%;background:var(--blue);border:2px solid var(--panel);box-shadow:0 0 0 1px var(--blue)}.event-dot.undated{background:var(--muted);box-shadow:0 0 0 1px var(--muted)}.event-dot.out_of_window{background:var(--gold);box-shadow:0 0 0 1px var(--gold)}.event-time{font-size:12px;color:var(--muted);display:flex;gap:8px;align-items:center;flex-wrap:wrap}.event-time>span:not(.badge){font-size:12px;color:var(--muted)}.event-title{display:flex;gap:7px;margin-top:8px;align-items:center;flex-wrap:wrap}.event-title .link{font-size:12px}.event-chain p{font-size:14px;color:var(--ink);line-height:1.8;margin:8px 0;overflow-wrap:anywhere}.event-actors{display:flex;gap:5px;flex-wrap:wrap}.event-actors .chip{font-size:12px}.event-support{display:flex;gap:6px;flex-wrap:wrap;font-size:12px;color:var(--muted);line-height:1.8;margin-top:8px}.event-support .link{font-size:12px}.event-pagination{display:flex;justify-content:flex-end;align-items:center;gap:10px;padding:10px 14px;font-size:12px;border-top:1px solid var(--selected);color:var(--muted)}.event-pagination button{padding:3px 8px}
.event-day-chart{padding:8px 12px;border-top:1px solid var(--selected)}.event-day-chart svg{display:block;width:100%}.focused .event-map{max-height:420px}
</style>
